    width: 100%;
    height: 100%;
    object-fit: cover;
    transition: transform 0.4s;
  }
  .card:hover img {
    transform: scale(1.1);
  }
  .overlay {
    position: absolute;
    bottom: -100%; /* initially hidden below */
    left: 0;
    width: 100%;
    height: 100%;
    background: linear-gradient(transparent, rgba(0,0,0,0.8));
    display: flex;
    flex-direction: column;
    justify-content: flex-end;
    padding: 20px;
    transition: bottom 0.4s ease;
  }
  .card:hover .overlay {
    bottom: 0;
  }
  .overlay h3 {
    color: white;
    font-size: 1.4em;
    margin-bottom: 5px;
  }
