```css
/* styles.css - Non-critical, lazy-loaded */
/* Grouped media queries instead of scattered */
.card-grid { ... }
@media (max-width: 768px) { .card-grid { ... } }

.footer { ... }
@media (max-width: 768px) { .footer { ... } }

/* Optimized with containment */
