  * { box-sizing: border-box; margin: 0; padding: 0; }
  body { font-family: Arial, sans-serif; padding: 40px; background: #f5f5f5; }

  .demo { max-width: 900px; margin: 0 auto; }

  h2 { margin-bottom: 20px; }

