    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 16px;
  }

  .label {
    font-size: 0.8rem;
    color: #888;
    text-align: center;
    margin-bottom: 6px;
    font-weight: 600;
  }

  .justify-start { justify-content: flex-start; }
  .justify-center { justify-content: center; }
  .justify-end { justify-content: flex-end; }
